custom_css:
:root {
    --screen-other-side-enabled: 1;
    --screen-ink: #eef0ff;
    --screen-muted: #b9bad9;
    --screen-ice: #82e4ff;
    --screen-violet: #cba4ff;
    --screen-glass: #141627;
    --screen-border: #565a86;
    --screen-wallpaper: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/wallpapers/chat-wallpaper.webp");
    --screen-drawer-art: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/wallpapers/settings-wallpaper.webp");
}

/* The built-in background picker remains the source of an installed wallpaper. */
body #bg1:not([style*="background-image"]):not([style*="background:"]) {
    background: var(--screen-wallpaper) center / cover no-repeat #131326;
}

#top-bar {
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/navigation/top-bar.png") center / 100% 100% no-repeat, #0e1124;
}

/* Retain the native panel DOM and its listeners when folding away its triggers. */
html[data-screen-launcher] body #top-bar#top-bar { display: none !important; }
html[data-screen-launcher] body #top-settings-holder#top-settings-holder {
    position: fixed !important;
    inset: 0 auto auto 0 !important;
    width: 0 !important;
    height: 0 !important;
    min-width: 0 !important;
    min-height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: visible !important;
    background: none !important;
    transform: none !important;
    pointer-events: none !important;
}
html[data-screen-launcher] #top-settings-holder > .drawer > .drawer-toggle { display: none !important; }
html[data-screen-launcher] body #top-settings-holder .drawer-content.openDrawer {
    position: fixed !important;
    top: max(8px, env(safe-area-inset-top, 0px)) !important;
    bottom: auto !important;
    left: 0 !important;
    right: 0 !important;
    margin-inline: auto !important;
    width: min(680px, calc(100vw - 16px)) !important;
    min-width: 0 !important;
    max-height: calc(100dvh - 22px - env(safe-area-inset-bottom, 0px)) !important;
    overflow-y: auto;
    pointer-events: auto !important;
}
html[data-screen-launcher] body #sheld {
    top: max(8px, env(safe-area-inset-top, 0px)) !important;
    bottom: max(4px, env(safe-area-inset-bottom, 0px)) !important;
    height: auto !important;
    max-height: none !important;
    margin-inline: auto !important;
}
html[data-screen-launcher] body #sheld #chat {
    padding-top: 56px !important;
    scroll-padding-top: 56px;
}

#screen-other-side-nav {
    position: fixed;
    top: max(7px, env(safe-area-inset-top, 0px));
    right: max(9px, env(safe-area-inset-right, 0px));
    z-index: 3999;
    display: flex;
    flex-direction: column;
    align-items: end;
    gap: 6px;
}
#screen-other-side-toggle {
    width: 52px;
    height: 52px;
    padding: 0;
    border: 1px solid #6b729a;
    border-radius: 50%;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/navigation/launcher-idle.png") center / contain no-repeat,
        linear-gradient(#82e4ff,#82e4ff) center / 16px 2px no-repeat, #131727;
    color: var(--screen-ice);
    cursor: pointer;
    touch-action: manipulation;
}
#screen-other-side-toggle[aria-expanded="true"] {
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/navigation/launcher-open.png"), linear-gradient(#cba4ff,#cba4ff);
    color: var(--screen-violet);
    border-color: #a376dc;
}
#screen-other-side-grid {
    width: min(296px, calc(100vw - 24px));
    box-sizing: border-box;
    max-height: calc(100dvh - 80px - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px));
    overflow: auto;
    padding: 18px 16px 22px;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
    border: 1px solid var(--screen-border);
    border-radius: 22px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/navigation/launcher-panel.png") center / 100% 100% no-repeat, #111425;
    box-shadow: 0 12px 35px #050610a0;
}
#screen-other-side-grid[hidden] { display: none !important; }
#screen-other-side-grid .screen-other-side-item {
    min-width: 0;
    min-height: 56px;
    display: grid;
    place-items: center;
    align-content: center;
    gap: 3px;
    padding: 4px 2px;
    cursor: pointer;
    touch-action: manipulation;
    border: 1px solid transparent;
    border-radius: 8px;
    background: #0d0e1b66;
    color: var(--screen-ink);
    font: inherit;
    font-size: 12px;
    line-height: 1.35;
}
#screen-other-side-grid .screen-other-side-item::before {
    content: "";
    width: 29px;
    height: 29px;
    background: var(--screen-icon) center / contain no-repeat;
}
#screen-other-side-grid .screen-other-side-item:is(:hover,:focus-visible,:active) {
    background: #423064;
    border-color: var(--screen-violet);
}
#screen-other-side-toggle:focus-visible, #screen-other-side-grid .screen-other-side-item:focus-visible {
    outline: 2px solid var(--screen-ice);
    outline-offset: 2px;
}

/* Settings windows use their own quiet wallpaper. */
#top-settings-holder .drawer-content,
.drawer-content:is(#left-nav-panel,#rm_api_block,#AdvancedFormatting,#WorldInfo,
    #user-settings-block,#Backgrounds,#rm_extensions_block,#PersonaManagement,#right-nav-panel,
    #completion_prompt_manager_popup) {
    color: var(--screen-ink);
    border-color: var(--screen-border);
    background: linear-gradient(#11132444,#11132488), var(--screen-drawer-art) center / cover no-repeat, #171729 !important;
}
#top-settings-holder :is(input[type="text"],input[type="number"],textarea,select),
#completion_prompt_manager_list {
    color: var(--screen-ink);
    background: #141528e8;
    border-color: var(--screen-border);
}
:is(.popup,.options-content,#toast-container .toast) {
    color: var(--screen-ink) !important;
    background-color: #15182a !important;
    border-color: var(--screen-border);
}

body #chat {
    container-type: inline-size;
    background: transparent !important;
    box-sizing: border-box;
    padding-inline: 0 !important;
}
#chat > .mes {
    --screen-bubble: min(96cqw, 720px);
    --screen-head: calc(var(--screen-bubble) * 0.2148);
    --screen-foot: calc(var(--screen-bubble) * 0.1444);
    position: relative;
    display: block !important;
    width: var(--screen-bubble) !important;
    max-width: 100% !important;
    flex: 0 0 auto !important;
    box-sizing: border-box;
    contain: none !important;
    content-visibility: visible !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    margin: calc(var(--screen-head) + 12px) auto var(--screen-foot) !important;
    padding: 27px 8% 12px !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    background: #111421 url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/chat/bubble-middle.png") center top / 100% auto repeat-y !important;
    color: var(--screen-ink);
}
#chat > .mes:last-of-type { margin-bottom: calc(var(--screen-foot) + 10px) !important; }
#chat > .mes::before, #chat > .mes::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    width: 100%;
    pointer-events: none;
    background: center / 100% 100% no-repeat;
}
#chat > .mes::before {
    bottom: calc(100% - 1px);
    height: var(--screen-head);
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/chat/bubble-top.png");
    z-index: 2;
}
#chat > .mes::after {
    top: calc(100% - 1px);
    height: var(--screen-foot);
    background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/chat/bubble-bottom.png");
}
#chat > .mes[is_user="true"]::after {
    filter: hue-rotate(-18deg);
}
#chat .mes .mes_block {
    position: static !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
}
#chat .mes :is(.mes_block,.mes_text) {
    contain: none !important;
    height: auto !important;
    max-height: none !important;
}
#chat .mes :is(.mesAvatarWrapper,.ch_name) {
    position: absolute !important;
    inset: auto 0 100% !important;
    width: 100% !important;
    height: var(--screen-head) !important;
    margin: 0 !important;
    padding: 0 !important;
    pointer-events: none;
}
#chat .mes .mesAvatarWrapper .avatar {
    position: absolute !important;
    top: 33.5%;
    left: 5.55%;
    width: 12.6% !important;
    height: calc(var(--screen-bubble) * .126) !important;
    z-index: 1;
    margin: 0 !important;
    border-radius: 50% !important;
    box-shadow: none !important;
    overflow: hidden;
    pointer-events: auto;
}
#chat .mes .mesAvatarWrapper .avatar img {
    display: block;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover;
    border: 0 !important;
    border-radius: inherit;
}
#chat .mes .mesAvatarWrapper {
    display: flex !important;
    z-index: auto !important;
    gap: 5px;
    align-items: flex-end;
    box-sizing: border-box;
    padding: 0 0 5% 25% !important;
}
#chat .mes :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay) {
    position: relative !important;
    z-index: 3;
    width: auto !important;
    margin: 0 !important;
    color: var(--screen-muted) !important;
    font-size: clamp(8px, 2cqw, 12px) !important;
    line-height: 1.1;
    white-space: nowrap;
}
#chat .mes .ch_name { z-index: 4; display: block !important; }
#chat .mes .name_text {
    position: absolute;
    left: 24%;
    top: 44%;
    max-width: 57%;
    font-size: clamp(13px, 4cqw, 24px);
    font-weight: 650;
    color: var(--screen-violet);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    pointer-events: auto;
}
#chat .mes[is_user="true"] .name_text { color: var(--screen-ice); }
#chat .mes .timestamp { position: absolute; top: 74%; right: 16%; color: var(--screen-muted) !important; }
#chat .mes :is(.mes_buttons,.mes_edit_buttons) {
    position: absolute !important;
    top: calc(var(--screen-head) + 3px);
    right: 7%;
    margin: 0 !important;
    flex-wrap: wrap;
    max-width: 85%;
    pointer-events: auto;
}
#chat .mes .extraMesButtons { background-color: #191c32; border-radius: 8px; }
#chat .mes :is(.swipe_left,.swipeRightBlock) {
    position: absolute !important;
    top: calc(100% + 2px) !important;
    bottom: auto !important;
    margin: 0 !important;
    z-index: 2;
}
#chat .mes .swipe_left { left: 8% !important; right: auto !important; }
#chat .mes .swipeRightBlock { right: 8% !important; left: auto !important; }
#chat .mes .swipes-counter { color: var(--screen-ink) !important; }
#chat .mes .mes_text { color: var(--screen-ink); line-height: 1.8; overflow-wrap: anywhere; }
#chat .mes_text q { color: var(--screen-ice); }
#chat .mes_text em { color: var(--screen-violet); }
#chat .mes_text blockquote { border-inline-start: 3px solid #8364bc; background: #23203c; }
#chat .mes_text :is(pre,code) { background: #1a1b33; color: var(--screen-ink); }
#chat .mes_text hr { border: 0; height: 1px; background: linear-gradient(90deg, transparent, #9873dc, #8de6ff, transparent); }
#chat .mes_reasoning_header {
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/thinking.png") left center / 20px auto no-repeat;
    padding-left: 26px;
}

body #form_sheld { background: transparent; }
body #send_form {
    position: relative;
    padding: 5px 8px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/chat/input-frame.png") center / 100% 100% no-repeat, #101326;
    border: 1px solid var(--screen-border);
    border-radius: 14px;
}
#send_form::before {
    content: "";
    position: absolute;
    right: 10px;
    bottom: 100%;
    width: 35px;
    height: 35px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/tentacle.png") center / contain no-repeat;
    pointer-events: none;
}
#send_form :is(#leftSendForm,#rightSendForm) { flex: 0 0 auto; }
#send_form #send_textarea { min-width: 0; color: var(--screen-ink); background: transparent; }
#send_textarea::placeholder { color: var(--screen-muted); }
#toast-container > .toast-success { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/check.png") !important; }
#toast-container > .toast-error { background-image: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/error.png") !important; }

@supports not (width: 1cqw) {
    #chat > .mes { --screen-bubble: min(720px, 94vw); }
}

#screen-other-side-grid [data-screen-icon="config"],
#top-settings-holder > #ai-config-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/config.png");
}

#screen-other-side-grid [data-screen-icon="api"],
#top-settings-holder > #sys-settings-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/api.png");
}

#screen-other-side-grid [data-screen-icon="format"],
#top-settings-holder > #advanced-formatting-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/format.png");
}

#screen-other-side-grid [data-screen-icon="worldbook"],
#top-settings-holder > #WI-SP-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/worldbook.png");
}

#screen-other-side-grid [data-screen-icon="settings"],
#top-settings-holder > #user-settings-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/settings.png");
}

#screen-other-side-grid [data-screen-icon="wallpaper"],
#top-settings-holder > #backgrounds-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/wallpaper.png");
}

#screen-other-side-grid [data-screen-icon="extensions"],
#top-settings-holder > #extensions-settings-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/extensions.png");
}

#screen-other-side-grid [data-screen-icon="persona"],
#top-settings-holder > #persona-management-button > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/persona.png");
}

#screen-other-side-grid [data-screen-icon="characters"],
#top-settings-holder > #rightNavHolder > .drawer-toggle .drawer-icon {
    --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/characters.png");
}

#top-settings-holder > .drawer > .drawer-toggle .drawer-icon[title],
#top-settings-holder > .drawer > .drawer-toggle .drawer-icon {
    background: var(--screen-icon, none) center / 27px 27px no-repeat;
}
#top-settings-holder > :is(#ai-config-button,#sys-settings-button,#advanced-formatting-button,#WI-SP-button,#user-settings-button,#backgrounds-button,#extensions-settings-button,#persona-management-button,#rightNavHolder) > .drawer-toggle .drawer-icon {
    color: transparent;
}
#options_button { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/menu.png"); }
#extensionsMenuButton { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/add.png"); }
#send_but { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/send.png"); }
#mes_stop .fa-circle-stop { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/stop.png"); }
.mes_button.mes_edit { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/edit.png"); }
.extraMesButtonsHint { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/more.png"); }
#favorite_button { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/star-outline.png"); }
#favorite_button.fav_on { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/star-filled.png"); }
.mes .swipe_left { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/arrow-left.png"); }
.mes .swipe_right { --screen-icon: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/arrow-right.png"); }

:is(#options_button,#extensionsMenuButton,#send_but,#mes_stop .fa-circle-stop,.mes_button.mes_edit,.extraMesButtonsHint,#favorite_button,#favorite_button.fav_on,.mes .swipe_left,.mes .swipe_right)::before {
    content: "" !important;
    display: inline-block;
    width: 22px;
    height: 22px;
    vertical-align: middle;
    background: var(--screen-icon) center / contain no-repeat;
}

#chat #show_more_messages { color: var(--screen-ice); background: #171a2d; }
.inline-drawer-icon.down::before {
    content: "" !important;
    display: inline-block;
    width: 18px;
    height: 18px;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/chevron-down.png") center / contain no-repeat;
}
#top-settings-holder .api_loading::before {
    content: "";
    display: inline-block;
    width: 22px;
    height: 22px;
    margin-inline-end: 5px;
    vertical-align: middle;
    background: url("https://cdn.jsdelivr.net/gh/Ttsningning/Orange-shop-assets1@aaae80d00abf022016815b143cc9b45091ec79ca/screen-other-side/icons/loading.png") center / contain no-repeat;
    animation: screen-other-side-spin 2s linear infinite;
}
@keyframes screen-other-side-spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) {
    #top-settings-holder .api_loading::before { animation: none; }
}
